const contract=()=>`${header()}<main><section class="contract-hero"><div class="container"><div class="copy reveal"><div class="breadcrumb" style="color:#6c7f8c">Início › Contratar</div><h1>Monte seu pedido em poucos passos.</h1><p>Escolha o produto, configure os detalhes e revise tudo antes de enviar.</p></div><div class="photo"><img src="${A('contract-hero.webp')}" alt="Especialista Telefonia Fácil"></div></div></section><div class="container"><div class="steps"><div class="step active"><div class="step-num">1</div><div><b>Produto</b><span>Escolha o que precisa</span></div></div><div class="step"><div class="step-num">2</div><div><b>Configuração</b><span>Personalize</span></div></div><div class="step"><div class="step-num">3</div><div><b>Carrinho</b><span>Revise o pedido</span></div></div><div class="step"><div class="step-num">4</div><div><b>Contato</b><span>Envie seus dados</span></div></div></div></div><section class="section section-soft" style="padding-top:28px"><div class="container contract-layout"><form class="form-panel" id="contractForm"><div class="contract-block"><div class="block-title"><div class="block-n">1</div><div><h2>Escolha o produto</h2><p>Selecione uma solução para começar sua contratação.</p></div></div><div class="option-grid">${[['Número Fixo',I.phone],['PABX em Nuvem',I.cloud],['0800 Empresarial',I.headset],['Telefonia Móvel',I.mobile],['SIP Trunk',I.server],['M2M / IoT',I.mobile],['URA Personalizada',I.headset],['Equipamentos e Locação',I.gear]].map((o,i)=>`<label class="option ${i===0?'active':''}"><input type="radio" name="produto" value="${o[0]}" ${i===0?'checked':''}>${o[1]}<b>${o[0]}</b><span>Veja planos e configuração do produto.</span></label>`).join('')}</div></div><div id="productExtras" class="product-extras"></div><div class="contract-block config-block" data-config-block><div class="block-title"><div class="block-n">2</div><div><h2>Configure o produto</h2><p>Escolha as opções compatíveis com sua solução.</p></div></div><div class="field-grid"><div class="field full"><label>Observações</label><textarea name="obs" rows="3" placeholder="Alguma informação adicional? (opcional)"></textarea></div></div></div><div class="contract-block company-block"><div class="block-title"><div class="block-n">3</div><div><h2>Seus dados</h2><p>Usaremos estes dados para confirmar disponibilidade e próximos passos.</p></div></div><div class="field-grid"><div class="field"><label>Empresa *</label><input name="empresa" required></div><div class="field"><label>CNPJ</label><input name="cnpj" placeholder="00.000.000/0000-00"></div><div class="field"><label>Nome completo *</label><input name="nome" required></div><div class="field"><label>E-mail corporativo *</label><input type="email" name="email" required></div><div class="field"><label>Telefone *</label><input name="telefone" required></div><div class="field"><label>Cargo</label><input name="cargo"></div></div></div><button class="btn btn-primary" type="submit">Adicionar ao carrinho ${I.arrow}</button><div class="notice" id="contractNotice"></div></form><aside class="summary-panel reveal"><h2>Seu pedido</h2><div class="summary-box"></div><div class="summary-note"><b>Configuração em montagem</b><br>O total é atualizado conforme o produto e as opções escolhidas.</div><button class="btn btn-primary summary-continue" type="submit" form="contractForm">Adicionar e continuar ${I.arrow}</button><a class="btn btn-outline" style="width:100%;margin-top:10px" href="${href('solucoes')}">Voltar às soluções</a></aside></div></section></main>${footer()}`;
