 contato:()=>`${header()}<main><section class="page-hero"><div class="container reveal"><div class="section-label">Atendimento consultivo</div><h1>Fale com um especialista.</h1><p>Conte o que sua empresa precisa e nossa equipe poderá orientar a solução mais adequada.</p></div></section><section class="section section-soft"><div class="container content-grid"><form class="form-panel reveal" id="contactForm"><div class="field-grid"><div class="field"><label>Nome *</label><input name="nome" required></div><div class="field"><label>Empresa *</label><input name="empresa" required></div><div class="field"><label>E-mail *</label><input type="email" name="email" required></div><div class="field"><label>Telefone *</label><input name="telefone" required></div><div class="field full"><label>Como podemos ajudar?</label><textarea name="mensagem" rows="5"></textarea></div></div><button class="btn btn-primary" type="submit" style="margin-top:16px">Preparar contato ${I.arrow}</button><div class="notice" id="contactNotice"></div></form><div class="copy reveal"><div class="section-label">Canais diretos</div><h2>Atendimento humano para decisões importantes.</h2><p><b>Telefone:</b> (19) 3199-4699<br><b>0800:</b> 0800 999 3199<br><b>E-mail:</b> contato@telefoniafacil.com.br</p><a class="btn btn-outline" href="mailto:contato@telefoniafacil.com.br">Enviar e-mail</a></div></div></section></main>${footer()}`,
 'politica-de-privacidade':()=>generic('Política de Privacidade','Página institucional preparada para receber o texto jurídico oficial da Telefonia Fácil.',[['Privacidade','O conteúdo jurídico final deve ser validado pela empresa antes da publicação.',I.shield]]),
 'termos-de-uso':()=>generic('Termos de Uso','Página institucional preparada para receber o texto jurídico oficial da Telefonia Fácil.',[['Termos','O conteúdo jurídico final deve ser validado pela empresa antes da publicação.',I.shield]])
