const categoryPlans=key=>plansCatalog[key]||[];
const equipmentCards=()=>equipmentCatalog.map(p=>`<article class="plan equipment-plan ${p.featured?'featured':''} reveal"><img src="${/^https?:/.test(p.img)?p.img:A(p.img)}" alt="${p.name}"><${p.featured?'span':'div'} class="tag">${p.featured?'Mais escolhido':'Disponível para locação'}</${p.featured?'span':'div'}><h3>${p.name}</h3><p>${p.desc}</p><div class="plan-price"><small>A partir de</small>${money(p.price)}<small>/mês</small></div><div class="equipment-term">Contrato de 48 meses</div><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><a class="btn ${p.featured?'btn-primary':'btn-outline'} configure-plan" href="${href('contratar')}?produto=Equipamentos%20e%20Loca%C3%A7%C3%A3o&plano=${encodeURIComponent(p.name)}">Configurar locação ${I.arrow}</a></article>`).join('');
const planCards=(key)=>key==='equipamentos'?equipmentCards():categoryPlans(key).length?categoryPlans(key).map((p,i)=>`<article class="plan ${p.featured?'featured':''} reveal">${p.featured?'<span class="tag">Mais escolhido</span>':''}<h3>${p.name}</h3><p>${p.description}</p><div class="plan-price">${money(p.price)}<small>/mês</small></div><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><a class="btn ${p.featured?'btn-primary':'btn-outline'} configure-plan" href="${href('contratar')}?produto=${encodeURIComponent(productData[key]?.title||key)}&plano=${encodeURIComponent(p.name)}">Configurar este plano ${I.arrow}</a></article>`).join(''):`<article class="plan featured reveal"><span class="tag">Configuração personalizada</span><h3>Projeto sob medida</h3><p>Dimensione a solução com base na sua operação.</p><div class="plan-price">Sob consulta</div><ul><li>Escopo definido com sua empresa</li><li>Configuração orientada</li><li>Suporte especializado</li></ul><a class="btn btn-primary" href="${href('contratar')}?produto=${encodeURIComponent(productData[key]?.title||key)}">Configurar minha solução ${I.arrow}</a></article>`;
const productView=productContent[page];
if(productView){
  const heads=[...document.querySelectorAll('.product-hero~.section .section-head h2')];
  const intros=[...document.querySelectorAll('.product-hero~.section .section-head p')];
  if(heads[0])heads[0].textContent=productView.resources;
  if(intros[0])intros[0].textContent=productView.intro;
  const scenarioHead=heads.find(h=>h.closest('.section-head')?.querySelector('.section-label')?.textContent.includes('Para diferentes cenários'));
  const scenarioIntro=intros.find(p=>p.closest('.section-head')?.querySelector('.section-label')?.textContent.includes('Para diferentes cenários'));
  const plansHead=heads.find(h=>h.closest('.section-head')?.querySelector('.section-label')?.textContent.includes('Planos e soluções'));
  const faqHead=heads.find(h=>h.closest('.section-head')?.querySelector('.section-label')?.textContent.includes('Dúvidas frequentes'));
  if(scenarioHead)scenarioHead.textContent=`Onde ${productData[page].title} gera mais valor`;
  if(scenarioIntro)scenarioIntro.textContent='Veja como essa solução se encaixa em diferentes operações e equipes.';
  if(plansHead)plansHead.textContent=productView.plans;
  if(faqHead)faqHead.textContent=productView.faq;
  document.querySelectorAll('.faq-q').forEach((button,index)=>{if(productView.questions[index])button.firstChild.textContent=productView.questions[index]});
  document.querySelectorAll('.faq-a div').forEach((answer,index)=>{if(productView.answers[index])answer.textContent=productView.answers[index]});
  const sticky=document.createElement('a'); sticky.className='product-sticky-cta'; sticky.href=`${href('contratar')}?produto=${encodeURIComponent(productData[page].title)}`; sticky.textContent='Contratar esta solução →'; document.body.appendChild(sticky);
}
