if(page==='planos'){
  const all=document.querySelector('.plans'), groups=[['Número Fixo','numero-fixo'],['PABX em Nuvem','pabx'],['0800 Empresarial','0800'],['SIP Trunk','sip-trunk'],['Telefonia Móvel','telefonia-movel'],['M2M / IoT','m2m'],['URA Personalizada','ura'],['Equipamentos e Locação','equipamentos']];
  if(all)all.innerHTML=groups.map(([label,key])=>`<div class="plan-group"><div class="section-label">${label}</div>${planCards(key)}</div>`).join('');
}
const cartKey='tf-cart-v1';
const readCart=()=>{try{return JSON.parse(localStorage.getItem(cartKey)||'[]')}catch{return[]}};
const saveCart=items=>{localStorage.setItem(cartKey,JSON.stringify(items));updateCartBadge()};
const updateCartBadge=()=>document.querySelectorAll('[data-cart-count]').forEach(el=>{const n=readCart().reduce((sum,item)=>sum+item.qty,0);el.textContent=n;el.hidden=!n});
const formatConfig=item=>Object.entries(item.config||{}).filter(([,value])=>value&&value!=='-').map(([key,value])=>`${key}: ${value}`).join(' · ');
const itemTotal=item=>Number(item.price||0)*Number(item.qty||1);
const cartSummary=items=>items.length?items.map((item,i)=>`<div class="cart-item"><div><b>${item.product}</b><span>${item.plan}</span><small>${item.price?money(item.price)+'/mês por unidade':'Sob consulta'}</small>${item.extras?.length?`<small>Adicionais: ${item.extras.join(', ')}</small>`:''}${formatConfig(item)?`<small>Configuração: ${formatConfig(item)}</small>`:''}</div><div class="cart-controls"><button type="button" data-cart-minus="${i}" aria-label="Reduzir quantidade">−</button><b>${item.qty}</b><button type="button" data-cart-plus="${i}" aria-label="Aumentar quantidade">+</button><button type="button" class="cart-remove" data-cart-remove="${i}">Remover</button></div><strong class="cart-item-total">${item.price?money(itemTotal(item))+'/mês':'Sob consulta'}</strong></div>`).join(''):'<div class="cart-empty"><h3>Seu carrinho está vazio.</h3><p>Escolha um plano em uma página de solução para começar.</p><a class="btn btn-primary" href="'+href('solucoes')+'">Ver soluções '+I.arrow+'</a></div>';
const initCart=()=>{
  const cart=document.getElementById('cartPage'), checkout=document.getElementById('checkoutSummary');
  const items=readCart();
  const total=items.reduce((s,i)=>s+itemTotal(i),0), hasQuote=items.some(i=>!i.price);
  const totalHtml=`<div class="cart-total"><span>Total mensal ${hasQuote?'estimado':'do pedido'}</span><b>${hasQuote?'Sob consulta':money(total)}</b></div>`;
  if(cart){cart.innerHTML=`<div class="cart-list">${cartSummary(items)}</div>${items.length?totalHtml+`<a class="btn btn-primary" href="${href('checkout')}">Continuar para seus dados ${I.arrow}</a>`:''}`;}
  if(checkout){checkout.innerHTML=items.length?cartSummary(items)+totalHtml:'<p>Seu carrinho está vazio. <a href="'+href('solucoes')+'">Escolha uma solução.</a></p>';}
  document.querySelectorAll('[data-cart-minus],[data-cart-plus],[data-cart-remove]').forEach(btn=>btn.addEventListener('click',()=>{const next=readCart(),i=Number(btn.dataset.cartMinus??btn.dataset.cartPlus??btn.dataset.cartRemove);if(btn.dataset.cartRemove!==undefined)next.splice(i,1);else next[i].qty=Math.max(0,next[i].qty+(btn.dataset.cartPlus!==undefined?1:-1));saveCart(next);initCart()}));
};
document.querySelectorAll('.add-plan').forEach(btn=>btn.addEventListener('click',()=>{const items=readCart(),key=`${btn.dataset.product}|${btn.dataset.plan}`;const existing=items.find(i=>i.key===key);if(existing)existing.qty++;else items.push({key,product:btn.dataset.product,plan:btn.dataset.plan,price:Number(btn.dataset.price),qty:1});saveCart(items);btn.textContent='Adicionado ✓';setTimeout(()=>{window.location.href=href('carrinho')},350)}));
updateCartBadge();
document.querySelectorAll('#contractForm .option').forEach(option=>option.addEventListener('click',()=>setTimeout(()=>{renderExtras();renderUpsells();renderPlanOptions();renderServiceConfigFixed();syncPlanTotal();refreshConfigSummary()},0)));
